class RenderCountrySelect {
  constructor({ el }) {
    this.DOM = document.querySelector(el);
    if (!this.DOM) return;

    this.trigger = this.DOM.querySelector('.select-trigger');
    this.optionList = this.DOM.querySelector('.select-options');
    this.hiddenInput = this.DOM.querySelector('input[name="country"]');

    this.init();
    this.bindEvents();
  }

  async init() {
    const { data } = await getCountryList();
    const currentCountry = data.name;
    const currentCountryCode = data.code;
    const countryList = data.province;

    this.renderOptions(countryList);
    if (currentCountry) {
      const countryEl = document.querySelector('.custom-current-country .current-country');
      countryEl.textContent = currentCountry;
      countryEl.setAttribute('data-country-code', currentCountryCode);
    }
    // 如果当前国家有值，可以预选中
    if (currentCountry) {
      const matched = countryList.find(item => item.name === currentCountry);
      if (matched) {
        this.selectOption(matched.code, matched.name);
      }
    }
  }

  renderOptions(countries) {
    if (!Array.isArray(countries)) return;

    const html = countries.map(item => {
      return `<li class="country-select-item" data-value="${item.code}">${item.name}</li>`;
    }).join('');
    this.optionList.innerHTML = html;
  }

  bindEvents() {
    // 查找箭头元素
    this.arrow = this.DOM.querySelector('.country-select-icon');

    // 为整个trigger添加点击事件
    this.trigger.addEventListener('click', () => {
      this.toggleDropdown();
    });

    // 为箭头单独添加点击事件
    if (this.arrow) {
      this.arrow.addEventListener('click', (e) => {
        e.stopPropagation(); // 阻止事件冒泡
        this.toggleDropdown();
      });
    }

    this.optionList.addEventListener('click', (e) => {
      const li = e.target.closest('li');
      if (!li) return;
      const value = li.getAttribute('data-value');
      const label = li.textContent;

      this.selectOption(value, label);
    });

    // 点击外部关闭
    document.addEventListener('click', (e) => {
      if (!this.DOM.contains(e.target)) {
        this.optionList.style.display = 'none';
      }
    });
  }

  // 切换下拉框显示/隐藏状态
  toggleDropdown() {
    this.optionList.style.display =
      this.optionList.style.display === 'block' ? 'none' : 'block';
  }

  selectOption(value, label) {
    // 更新文字
    this.trigger.textContent = label;
    this.trigger.style.color = '#222';

    // 更新隐藏 input
    this.hiddenInput.value = value;

    // 高亮选中的项
    const allItems = this.optionList.querySelectorAll('li');
    allItems.forEach(li => {
      if (li.getAttribute('data-value') === value) {
        li.classList.add('selected');
      } else {
        li.classList.remove('selected');
      }
    });

    // 关闭下拉
    this.optionList.style.display = 'none';
  }
}

class MultiSelectDropdown {
  constructor({ el }) {
    this.DOM = document.querySelector(el);
    if (!this.DOM) return;

    this.display = this.DOM.querySelector('.select-display');
    this.optionsBox = this.DOM.querySelector('.select-options');
    this.selectedItemsBox = this.DOM.querySelector('.product-selected-items');
    this.placeholder = this.DOM.querySelector('.placeholder');
    this.hiddenInput = this.DOM.querySelector('input[type="hidden"]');
    this.errorEl = document.querySelector('[data-product-use-error]');
    this.selectedValues = [];

    // 防止重复绑定事件的标志
    this.eventsbound = false;
    // 存储事件处理器引用，便于移除
    this.removeTagHandler = null;
    this.outsideClickHandler = null;
    this.clickTimeout = null;

    this.init();
  }

  async init() {
    try {
      const { data } = await getGoodsList(); // 接口返回格式：{ sku, originTitle }
      const options = data
        .filter(item => item.originTitle)
        .map(item => ({
          value: item.originTitle,
          label: item.originTitle,
        }));
      this.renderOptions(options);
      this.bindEvents();
    } catch (err) {
      console.error('获取商品列表失败:', err);
    }
  }

  renderOptions(options) {
    this.options = options;

    // 生成常规选项的HTML
    let optionsHTML = options.map(opt => `
      <li data-value="${opt.value}" class="flex-between">
        <span class="label">${opt.label}</span>
        <span class="check">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20">
            <g fill-rule="nonzero" fill="none">
              <path fill="none" d="M0 0h20v20H0z" />
              <path fill="#1A1A1A" opacity=".9" d="M3.537 8.324l5.966 5.966-1.326 1.326-5.966-5.967z" />
              <path fill="#1A1A1A" opacity=".9" d="M17.789 6.003l-9.612 9.613-1.326-1.326 9.613-9.612z" />
            </g>
          </svg>
        </span>
      </li>`).join('');

      // 将特殊选项也添加到options数组中，以便其他方法能正确处理
    this.options = [...options];
    this.optionsBox.innerHTML = optionsHTML;
  }

  bindEvents() {
    // 防止重复绑定事件
    if (this.eventsbound) return;
    this.eventsbound = true;

    this.display.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggleDropdown();
    });

    // 使用事件委托处理选项点击，防止事件冒泡导致的多次触发
    this.optionsBox.addEventListener('click', (e) => {
      e.stopPropagation();
      const li = e.target.closest('li');
      if (!li) return;

      const value = li.dataset.value;
      if (!value) return;

      // 防止重复点击同一选项
      if (li.classList.contains('processing')) return;
      li.classList.add('processing');

      // 立即处理选择逻辑，不使用防抖
      const isSelected = this.selectedValues.includes(value);
      if (isSelected) {
        this.selectedValues = this.selectedValues.filter(v => v !== value);
      } else {
        this.selectedValues.push(value);
      }

      this.updateSelectedDisplay();

      // 移除处理标志
      setTimeout(() => {
        li.classList.remove('processing');
      }, 100);
    });

    // 点击外部关闭下拉
    this.outsideClickHandler = (e) => {
      if (!this.DOM.contains(e.target)) {
        this.optionsBox.style.display = 'none';
      }
    };
    document.addEventListener('click', this.outsideClickHandler);

    // 监听重置选择事件
    this.DOM.addEventListener('reset-selection', () => {
      this.resetSelection();
    });
  }

  // 重置选择状态
  resetSelection() {
    this.selectedValues = [];
    this.updateSelectedDisplay();

    // 更新选项列表中的选中状态
    this.optionsBox.querySelectorAll('li').forEach(li => {
      li.classList.remove('selected');
    });
  }

  toggleDropdown() {
    const isOpen = this.optionsBox.style.display === 'block';
    this.optionsBox.style.display = isOpen ? 'none' : 'block';
  }

  updateSelectedDisplay() {
    // 清空选中显示区域
    this.placeholder.innerHTML = '';
    this.placeholder.classList.remove('empty');
    this.selectedItemsBox.innerHTML = '';

    if (this.selectedValues.length === 0) {
      this.placeholder.innerText = 'Please select related product';
      this.placeholder.classList.add('empty');
    }

    // 使用文档片段提高性能
    const fragment = document.createDocumentFragment();
    this.selectedValues.forEach(val => {
      const label = this.options.find(opt => opt.value === val)?.label || val;
      const tag = document.createElement('div');
      tag.className = 'selected-tag';
      tag.innerHTML = `${label} <span data-remove="${val}">×</span>`;
      fragment.appendChild(tag);
    });
    this.selectedItemsBox.appendChild(fragment);

    // 设置隐藏字段值
    this.hiddenInput.value = this.selectedValues.join(',');

    // 更新 options 勾选状态
    this.optionsBox.querySelectorAll('li').forEach(li => {
      const val = li.dataset.value;
      li.classList.toggle('selected', this.selectedValues.includes(val));
    });

    // 只在第一次初始化时绑定删除标签的事件处理器
    if (!this.removeTagHandler) {
      this.removeTagHandler = (e) => {
        const removeBtn = e.target.closest('[data-remove]');
        if (removeBtn) {
          e.stopPropagation();
          const val = removeBtn.dataset.remove;
          // 确保值存在于数组中再移除
          if (this.selectedValues.includes(val)) {
            this.selectedValues = this.selectedValues.filter(v => v !== val);
            this.updateSelectedDisplay();
          }
        }
      };
      this.selectedItemsBox.addEventListener('click', this.removeTagHandler);
    }

    // 更新校验显示（非空时隐藏错误提示）
    if (this.errorEl && this.selectedValues.length > 0) {
      this.errorEl.classList.add('hidden');
    }
  }

  // 可暴露校验方法，供外部调用
  validate() {
    if (this.selectedValues.length === 0) {
      this.errorEl?.classList.remove('hidden');
      return false;
    } else {
      this.errorEl?.classList.add('hidden');
      return true;
    }
  }

  // 提供获取值方法（可选）
  getValue() {
    return this.selectedValues;
  }
}
